// Regenerate from Node's ECMA-262 u-mode matcher, never from an evaluator.
// Run: node tests/fixtures/lone-surrogate.mjs (from crates/openbindings-json-schema-evaluator).
import { writeFileSync } from "node:fs";

const rows = ["# id\tpattern\tinput\tmatches (Node RegExp u)"];
const inputs = ["", "abc", "a", "😀", "abc😀"];
const add = (id, pattern) => {
  const regex = new RegExp(pattern, "u");
  inputs.forEach((input, i) =>
    rows.push(`${id}/${i}\t${pattern}\t${input}\t${regex.test(input)}`),
  );
};
for (const [name, escape] of [
  ["high", String.raw`\ud83d`],
  ["low", String.raw`\ude00`],
  ["braced-high", String.raw`\u{d83d}`],
  ["braced-low", String.raw`\u{de00}`],
]) {
  for (const [label, quantifier] of [
    ["optional", "?"],
    ["star", "*"],
    ["zero-bounded", "{0,2}"],
    ["plus", "+"],
    ["positive-bounded", "{1,2}"],
    ["optional-lazy", "??"],
    ["star-lazy", "*?"],
    ["zero-bounded-lazy", "{0,2}?"],
  ]) {
    add(`${name}/${label}`, `^[a-z]*${escape}${quantifier}$`);
    add(`${name}/class-${label}`, `^[a-z]*[${escape}]${quantifier}$`);
  }
  add(`${name}/bare`, `^${escape}$`);
  add(`${name}/unanchored-star`, `${escape}*`);
  add(`${name}/mixed-class`, `^[a${escape}]+$`);
  add(`${name}/negated-class`, `^[^${escape}]+$`);
  add(`${name}/alternate`, `^(?:${escape}|abc)$`);
  add(`${name}/alternate-optional`, `^(?:${escape}|abc)?$`);
  add(`${name}/lookbehind`, `(?<=${escape}?)abc$`);
}
add("paired", String.raw`^\ud83d\ude00$`);
add("scalar-braced", String.raw`^\u{1f600}$`);
writeFileSync(new URL("lone-surrogate.tsv", import.meta.url), `${rows.join("\n")}\n`);
console.log(`${rows.length - 1} cases generated by Node ${process.version}, V8 ${process.versions.v8}`);
